"""
``qtile events``: print the events published by a running qtile.

Connects to the event feed socket and writes one JSON object per line to stdout.
Error messages sent to stderr so as not to pollute pure JSON on stdout.
"""

from __future__ import annotations

import json
import os
import socket
import sys
from typing import TYPE_CHECKING, NoReturn

from libqtile import ipc
from libqtile.events import PROTOCOL_VERSION

if TYPE_CHECKING:
    import argparse

# Messages generated by the feed itself rather than by a hook. They are always
# shown, whatever the event filter says.
_CONTROL_EVENTS = {"hello"}


def default_socket_path() -> str:
    """The event socket lives next to the IPC socket, with an ``.events`` suffix."""
    return ipc.find_sockfile() + ".events"


def _error(message: str) -> NoReturn:
    print(f"qtile events: {message}", file=sys.stderr)
    sys.exit(1)


def _split_events(values: list[str] | None) -> list[str]:
    """Accept both ``-e a -e b`` and ``-e a,b``."""
    names: list[str] = []
    for value in values or []:
        names.extend(n.strip() for n in value.split(",") if n.strip())
    return names


def _connect(path: str) -> socket.socket:
    sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    try:
        sock.connect(path)
    except FileNotFoundError:
        sock.close()
        _error(f"no event socket at {path}. Is qtile running with the event feed enabled?")
    except ConnectionRefusedError:
        sock.close()
        _error(f"connection refused on {path}.")
    except OSError as e:
        sock.close()
        _error(f"cannot connect to {path}: {e}")
    return sock


def qtile_events(args: argparse.Namespace) -> None:
    try:
        path = args.socket or default_socket_path()
    except ipc.IPCError as e:
        _error(str(e))

    wanted = _split_events(args.events)
    sock = _connect(path)

    request: dict[str, object] = {}
    if wanted:
        request["subscribe"] = wanted

    seen = 0
    try:
        with sock, sock.makefile("rw", encoding="utf-8", newline="\n") as stream:
            if request:
                stream.write(json.dumps(request) + "\n")
                stream.flush()

            for line in stream:
                try:
                    msg = json.loads(line)
                except ValueError:
                    continue

                event = msg.get("event")
                if event == "hello":
                    version = msg.get("args", [{}])[0].get("version")
                    if version != PROTOCOL_VERSION:
                        _error(
                            f"server speaks event protocol version {version}, "
                            f"this client speaks {PROTOCOL_VERSION}"
                        )
                    if not args.hello:
                        continue

                try:
                    print(json.dumps(msg, indent=2 if args.pretty else None), flush=True)
                except BrokenPipeError:
                    # Downstream closed. Should be be treated as an error.
                    # Point stdout at devnull so interpreter shutdown doesn't complain.
                    os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
                    return

                if args.count and event not in _CONTROL_EVENTS:
                    seen += 1
                    if seen >= args.count:
                        return
            else:
                # Loop ended without break: the server closed the connection.
                _error("connection closed by qtile")
    except KeyboardInterrupt:
        return


def add_subcommand(subparsers, parents):
    parser = subparsers.add_parser(
        "events",
        parents=parents,
        help="Stream events (hooks) from a running qtile as JSON lines.",
    )
    parser.add_argument(
        "-s",
        "--socket",
        action="store",
        type=str,
        default=None,
        help="Event socket to connect to. Defaults to the IPC socket path plus '.events'.",
    )
    parser.add_argument(
        "-e",
        "--event",
        action="append",
        dest="events",
        metavar="NAME",
        help="Only show this event. May be repeated or comma-separated. Default: all events.",
    )
    parser.add_argument(
        "-n",
        "--count",
        type=int,
        default=0,
        metavar="N",
        help="Exit after N events (hello messages don't count).",
    )
    parser.add_argument(
        "--hello",
        action="store_true",
        default=False,
        help="Also print the server's initial hello message.",
    )
    parser.add_argument(
        "--pretty",
        action="store_true",
        default=False,
        help="Indent the JSON output (one multi-line object per event).",
    )
    parser.set_defaults(func=qtile_events)
